CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, username TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, age INTEGER NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS characters (id UUID PRIMARY KEY, user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, gender TEXT NOT NULL, skin TEXT NOT NULL, hair TEXT NOT NULL, style TEXT NOT NULL, background TEXT NOT NULL, neighborhood TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());